//! Byte helpers matching `<cctype>` behaviour in the "C" locale.
//!
//! `std::toupper` / `std::tolower` / `std::isalnum` only ever touch ASCII there,
//! so every byte >= 0x80 (e.g. the two bytes of a UTF-8 `ü`) is left alone and
//! is not considered alphanumeric.

/// `std::tolower` for a single byte.
pub fn to_lower(byte: u8) -> u8 {
    if byte.is_ascii_uppercase() {
        byte + 32
    } else {
        byte
    }
}

/// `std::toupper` for a single byte.
pub fn to_upper(byte: u8) -> u8 {
    if byte.is_ascii_lowercase() {
        byte - 32
    } else {
        byte
    }
}

/// `std::isalnum` for a single byte.
pub fn is_alnum(byte: u8) -> bool {
    byte.is_ascii_alphanumeric()
}

/// `std::isspace` for a single byte: space, \t, \n, \v, \f, \r.
pub fn is_space(byte: u8) -> bool {
    byte == b' ' || (0x09..=0x0d).contains(&byte)
}

/// Lower-cases every ASCII letter of `bytes`, leaving everything else as is.
pub fn to_lower_all(bytes: &[u8]) -> Vec<u8> {
    bytes.iter().copied().map(to_lower).collect()
}

