//! Emulation of the C runtime routines `test11.cpp` calls directly.

use crate::ascii;

/// `std::atoi`: `strtol` with base 10, saturated to `long` on overflow and then
/// narrowed to `int`. Non-numeric input yields `0`, trailing garbage is ignored.
pub fn atoi(text: &[u8]) -> i32 {
    let mut i = 0;
    while i < text.len() && ascii::is_space(text[i]) {
        i += 1;
    }

    let negative = match text.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let mut value: i64 = 0;
    let mut overflow = false;
    while i < text.len() && text[i].is_ascii_digit() {
        let digit = i64::from(text[i] - b'0');
        match value.checked_mul(10).and_then(|v| v.checked_add(digit)) {
            Some(v) => value = v,
            None => overflow = true,
        }
        i += 1;
    }

    // strtol clamps to LONG_MAX / LONG_MIN, atoi then truncates to int.
    if overflow {
        return if negative { i64::MIN as i32 } else { i64::MAX as i32 };
    }
    let value = if negative { -value } else { value };
    value as i32
}

#[cfg(test)]
mod tests {
    use super::atoi;

    #[test]
    fn matches_c_atoi() {
        assert_eq!(atoi(b"1"), 1);
        assert_eq!(atoi(b"abc"), 0);
        assert_eq!(atoi(b""), 0);
        assert_eq!(atoi(b" 42"), 42);
        assert_eq!(atoi(b"42abc"), 42);
        assert_eq!(atoi(b"+7"), 7);
        assert_eq!(atoi(b"0x1A"), 0);
        assert_eq!(atoi(b"3.9"), 3);
        assert_eq!(atoi(b"99999999999"), 1215752191);
        assert_eq!(atoi(b"-99999999999"), -1215752191);
        assert_eq!(atoi(b"9999999999999999999999"), -1);
        assert_eq!(atoi(b"-9999999999999999999999"), 0);
    }
}

