//! Port of `tests/test11.cpp`: exercises 11 `Inflector` entry points.
//!
//! Usage: `test11 <number> <word>` — with fewer than two arguments the program
//! prints nothing, mirroring the C++ `if (argc > 2)` guard.
//!
//! Built either as part of the Cargo package (`cargo build --release`) or
//! standalone with `rustc test11.rs`; the `#[path]` attribute makes the library
//! modules available in both cases.

#[path = "src/lib.rs"]
mod inflection;

use std::env;
use std::io::{self, BufWriter, Write};

use inflection::cstdlib::atoi;
use inflection::inflector::Inflector;

fn main() {
    Inflector::initialize();

    let args: Vec<String> = env::args().collect();

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    if args.len() > 2 {
        let num = atoi(args[1].as_bytes());
        let word = args[2].as_bytes();

        // 11 API calls
        line(&mut out, &Inflector::pluralize(word));
        line(&mut out, Inflector::ordinalize(num).as_bytes());
        line(&mut out, &Inflector::camelize(word, true));
        line(&mut out, &Inflector::camelize(word, false));
        line(&mut out, &Inflector::titleize(word));
        line(&mut out, &Inflector::capitalize(word));
        line(&mut out, &Inflector::truncate(word, 5));
        line(&mut out, &Inflector::truncate_with(word, 10, b"~"));
        line(&mut out, &Inflector::parameterize(word));
        line(&mut out, &Inflector::parameterize_with(word, b"_"));
        line(&mut out, if Inflector::is_plural(word) { b"1" } else { b"0" });
    }

    out.flush().expect("failed to write to stdout");
}

/// Writes one `std::cout << value << std::endl` line. Values are byte strings
/// because the C++ original may split a multi-byte character while truncating.
fn line<W: Write>(out: &mut W, value: &[u8]) {
    out.write_all(value).expect("failed to write to stdout");
    out.write_all(b"\n").expect("failed to write to stdout");
}

