        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

fn main() {
    let mut rng = Rng(0x2545F4914F6CDD1D);
    let out = io::stdout();
    let mut out = io::BufWriter::new(out.lock());

    let numbers = [
        "0", "1", "2", "3", "4", "5", "10", "11", "12", "13", "14", "20", "21", "22", "23", "100",
        "101", "111", "112", "113", "1000", "1001", "1013", "-1", "-11", "-21", "2147483647",
        "-2147483648", "abc", "", " 42", "42abc", "+7", "0x1A", "3.9", "99999999999",
        "9999999999999999999999", "-9999999999999999999999",
    ];

    let words = "cat dog child person mouse house box church city baby bus quiz leaf knife wolf \
        potato tomato photo piano hero echo man woman goose tooth foot sheep fish deer series \
        species analysis crisis datum medium index matrix vertex ox radius cactus fungus alumnus \
        criterion phenomenon equipment information rice money jeans police news music water \
        luggage furniture advice knowledge homework aircraft salmon trout moose offspring bison \
        swine cod scissors trousers glasses corps means mice geese teeth feet men women oxen \
        indices matrices vertices data media criteria phenomena analyses crises children people \
        brethren dice louse lice ice nice slice price twice octopi viri virus octopus pasta trivia \
        idea villa arena extra sofa Fish FISH Sheep Series Money Rice Data MICE Mice CATS Cats \
        hello_world foo_bar_baz FooBar fooBar _foo foo_ foo__bar foo_1bar a_b_c 9foo_bar \
        HELLO_WORLD Hello_World status alias bases axes crises testis shoes movies databases \
        buses hives lives wives knives quizzes news s ss sss a i o zz \
        equipments polices fishs sheeps"
        .split_whitespace()
        .map(str::to_string)
        .collect::<Vec<_>>();

    let mut emit = |n: &str, w: &str, out: &mut dyn Write| {
        writeln!(out, "{n}\t{w}").unwrap();
    };

    // Curated words against every number.
    for w in &words {
        for n in numbers {
            emit(n, w, &mut out);
        }
    }

    // Multi-word / punctuated inputs.
    let phrases = [
        "hello world",
        "Hello-World",
        "ABC def",
        "hello, world!",
        "  spaced   out  ",
        "a--b",
        "a__b",
        "! a",
        "a !",
        " ",
        "  ",
        "_a_",
        "-a-",
        ".a.",
        "a b",
        "a  b",
        "",
        "über",
        "café au lait",
        "naïve_person",
        "ÜBER ALLES",
        "MiXeD_CaSe words-here 123",
        "one two three four five",
        "trailing space ",
        " leading space",
        "tab\tseparated words",
        "12345",
        "!@#$%^&*()",
        "a1_b2-c3 d4",
    ];
    for w in phrases {
        for n in ["1", "2", "3", "11", "-5"] {
            emit(n, w, &mut out);
        }
    }

    // Every 3-byte lowercase suffix behind a neutral prefix: pins down the
    // suffix-driven rules.
    for a in b'a'..=b'z' {
        for b in b'a'..=b'z' {
            for c in b'a'..=b'z' {
                let w = format!("zz{}{}{}", a as char, b as char, c as char);
                emit(numbers[rng.below(numbers.len())], &w, &mut out);
            }
        }
    }

    // All one and two byte words.
    let alphabet: Vec<u8> = (0x20u8..0x7f).chain(0xc3..=0xc3).collect();
    for &a in &alphabet {
        let w = String::from_utf8_lossy(&[a]).to_string();
        emit("7", &w, &mut out);
        for &b in &alphabet {
            let bytes = [a, b];
            if let Ok(w) = std::str::from_utf8(&bytes) {
                emit("8", w, &mut out);
            }
        }
    }

    // Random strings over a nasty alphabet.
    let chars: Vec<&str> = "a b c z A Z 0 9 _ - . ! space , / ' \" é ü 漢"
        .split(' ')
        .map(|s| if s == "space" { " " } else { s })
        .collect();
    for _ in 0..8000 {
        let len = rng.below(14);
        let mut w = String::new();
        for _ in 0..len {
            w.push_str(chars[rng.below(chars.len())]);
        }
        if w.contains('\t') || w.contains('\n') {
            continue;
        }
        emit(numbers[rng.below(numbers.len())], &w, &mut out);
    }

    // Number sweep against a fixed word.
    for n in -300..=300 {
        emit(&n.to_string(), "widget", &mut out);
    }
    for n in [
        1000000, 1000001, 1000011, 1000013, 2147483646, -2147483647, 123456789, 987654321,
    ] {
        emit(&n.to_string(), "widget", &mut out);
    }
}

