//! Inflection rule tables registered by `Inflector::initialize()`.
//!
//! All comparisons are case sensitive, exactly like the original: `"Fish"`
//! pluralizes to `"Fishs"` and `"Mice"` is not recognised as a plural.

/// Words the pluralizer leaves untouched and that are never reported as plural.
pub const UNCOUNTABLE: [&[u8]; 10] = [
    b"equipment",
    b"information",
    b"rice",
    b"money",
    b"species",
    b"series",
    b"fish",
    b"sheep",
    b"jeans",
    b"police",
];

/// Endings whose singularization rule fires even though the word does not end
/// in `s`: `([ti])a -> \1um`, `(m|l)ice -> \1ouse`, `(octop|vir)i -> \1us`.
/// A word carrying one of them is therefore already a plural.
pub const PLURAL_ENDINGS: [&[u8]; 6] = [b"ia", b"ta", b"mice", b"lice", b"octopi", b"viri"];

/// Whole words recognised as plurals: `^(ox)en$ -> \1`.
pub const PLURAL_WORDS: [&[u8]; 1] = [b"oxen"];

pub fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLE.contains(&word)
}

