    }

    /// [`Inflector::truncate_with`] with the default `"..."` omission.
    pub fn truncate(word: &[u8], length: usize) -> Vec<u8> {
        Self::truncate_with(word, length, DEFAULT_OMISSION)
    }

    /// Lower-cases alphanumerics, turns spaces into `separator`, drops every
    /// other byte, then trims leading and trailing separators. Note that `_`
    /// and `-` are dropped rather than replaced: `"hello_world" ->
    /// "helloworld"`, while `"hello world" -> "hello-world"`.
    pub fn parameterize_with(word: &[u8], separator: &[u8]) -> Vec<u8> {
        let mut result = Vec::with_capacity(word.len());
        for &byte in word {
            if ascii::is_alnum(byte) {
                result.push(ascii::to_lower(byte));
            } else if byte == b' ' {
                result.extend_from_slice(separator);
            }
        }

        if separator.is_empty() {
            return result;
        }
        let mut start = 0;
        while result[start..].starts_with(separator) {
            start += separator.len();
        }
        let mut end = result.len();
        while end - start >= separator.len() && result[..end].ends_with(separator) {
            end -= separator.len();
        }
        result[start..end].to_vec()
    }

    /// [`Inflector::parameterize_with`] with the default `"-"` separator.
    pub fn parameterize(word: &[u8]) -> Vec<u8> {
        Self::parameterize_with(word, DEFAULT_SEPARATOR)
    }

    /// True when a singularization rule would change the word: it ends in `s`,
    /// carries one of the [`rules::PLURAL_ENDINGS`], or is a whole-word plural
    /// such as `oxen`. Uncountable words and the self-mapping endings of
    /// [`rules::SINGULAR_ENDINGS`] are never plural.
    pub fn is_plural(word: &[u8]) -> bool {
        if word.is_empty() || rules::is_uncountable(word) {
            return false;
        }
        if rules::PLURAL_WORDS.contains(&word) {
            return true;
        }
        if rules::SINGULAR_ENDINGS
            .iter()
            .any(|ending| word.ends_with(ending))
        {
            return false;
        }
        word.ends_with(b"s")
            || rules::PLURAL_ENDINGS
                .iter()
                .any(|ending| word.ends_with(ending))
    }
}

#[cfg(test)]
mod tests {
    use super::Inflector;

    #[test]
    fn pluralize_appends_s_and_honours_uncountables() {
        assert_eq!(Inflector::pluralize(b"cat"), b"cats");
        assert_eq!(Inflector::pluralize(b"child"), b"childs");
        assert_eq!(Inflector::pluralize(b"box"), b"boxs");
        assert_eq!(Inflector::pluralize(b"sheep"), b"sheep");
        assert_eq!(Inflector::pluralize(b"Sheep"), b"Sheeps");
        assert_eq!(Inflector::pluralize(b""), b"");
    }

    #[test]
    fn ordinalize_suffixes() {
        let cases = [
            (0, "0th"),
            (1, "1st"),
            (2, "2nd"),
            (3, "3rd"),
            (11, "11th"),
            (12, "12th"),
            (13, "13th"),
            (21, "21st"),
            (101, "101st"),
            (111, "111th"),
            (-1, "-1th"),
        ];
        for (number, expected) in cases {
            assert_eq!(Inflector::ordinalize(number), expected);
        }
    }

    #[test]
    fn camelize_only_consumes_underscores() {
        assert_eq!(Inflector::camelize(b"hello_world", true), b"helloWorld");
        assert_eq!(Inflector::camelize(b"hello_world", false), b"HelloWorld");
        assert_eq!(Inflector::camelize(b"Hello-World", true), b"Hello-World");
        assert_eq!(Inflector::camelize(b"foo__bar", true), b"fooBar");
        assert_eq!(Inflector::camelize(b"_", false), b"");
    }

    #[test]
    fn titleize_and_capitalize() {
        assert_eq!(Inflector::titleize(b"ABC def"), b"Abc Def");
        assert_eq!(Inflector::capitalize(b"ABC def"), b"Abc def");
        assert_eq!(Inflector::titleize(b"hello_world"), b"Hello_world");
        assert_eq!(Inflector::titleize(b"a  b"), b"A  B");
    }

    #[test]
    fn truncate_boundaries() {
        assert_eq!(Inflector::truncate(b"abcde", 5), b"abcde");
        assert_eq!(Inflector::truncate(b"abcdef", 5), b"ab...");
        assert_eq!(Inflector::truncate_with(b"abcdefghijk", 10, b"~"), b"abcdefghi~");
        assert_eq!(Inflector::truncate_with(b"abcdefghij", 10, b"~"), b"abcdefghij");
    }

    #[test]
    fn parameterize_drops_punctuation() {
        assert_eq!(Inflector::parameterize(b"hello_world"), b"helloworld");
        assert_eq!(Inflector::parameterize(b"hello world"), b"hello-world");
        assert_eq!(Inflector::parameterize_with(b"hello world", b"_"), b"hello_world");
        assert_eq!(Inflector::parameterize(b"  spaced   out  "), b"spaced---out");
        assert_eq!(Inflector::parameterize(b"!!!"), b"");
        assert_eq!(Inflector::parameterize(b"  "), b"");
    }

    #[test]
    fn is_plural_predicate() {
        for word in ["cats", "s", "ss", "news", "mice", "slice", "oxen", "data", "octopi", "viri"] {
            assert!(Inflector::is_plural(word.as_bytes()), "{word}");
        }
        for word in ["cat", "mouse", "children", "geese", "CATS", "Mice", "zzoxen", "fish", "jeans", ""] {
            assert!(!Inflector::is_plural(word.as_bytes()), "{word}");
        }
    }
}
